import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom"; // useNavigate instead of useHistory
// reactstrap components
import {
  DropdownMenu,
  DropdownItem,
  UncontrolledDropdown,
  DropdownToggle,
  Media,
  Nav,
  Container,
  Navbar,
} from "reactstrap";
import { getAuth, signOut } from "firebase/auth"; // Updated Firebase imports
import { getFirestore, doc, getDoc } from "firebase/firestore"; // Importing Firestore functions

const AdminNavbar = (props) => {
  const navigate = useNavigate(); // Use useNavigate for navigation
  const [firstName, setFirstName] = useState("Loading..."); // Set initial state as 'Loading...'

  // Fetch firstName from Firestore when component mounts
  useEffect(() => {
    const auth = getAuth();
    const user = auth.currentUser; // Get the current logged-in user
    if (user) {
      const db = getFirestore();
      const userRef = doc(db, "users", user.uid); // Referencing user's document in Firestore
      getDoc(userRef)
        .then((docSnap) => {
          if (docSnap.exists()) {
            const userData = docSnap.data();
            const fetchedFirstName = userData.firstName;
            console.log("Fetched first name: ", fetchedFirstName); // Log the fetched firstName
            setFirstName(fetchedFirstName || "fetchedFirstName"); // Set firstName from Firestore or default to "User"
          } else {
            console.log("No user data found!");
            setFirstName("User"); // Default value if no data exists
          }
        })
        .catch((error) => {
          console.error("Error fetching user data: ", error);
          setFirstName("User"); // Default on error
        });
    }
  }, []);

  // Function to handle logout
  const handleLogout = async () => {
    try {
      const auth = getAuth(); // Get Firebase Auth instance
      await signOut(auth); // Sign out from Firebase
      console.log("User logged out successfully");

      // Redirect to the login page after logout
      navigate("/login");
    } catch (error) {
      console.error("Error logging out: ", error);
    }
  };

  return (
    <>
      <Navbar className="navbar-top navbar-dark" expand="md" id="navbar-main">
        <Container fluid>
          <Link
            className="h4 mb-0 text-white text-uppercase d-none d-lg-inline-block"
            to="/"
          >
            {props.brandText}
          </Link>
          <Nav className="align-items-center d-none d-md-flex" navbar>
            <UncontrolledDropdown nav>
              <DropdownToggle className="pr-0" nav>
                <Media className="align-items-center">
                  <span className="avatar avatar-sm rounded-circle">
                    <img
                      alt="..."
                      src={require("../../assets/img/theme/team-4-800x800.jpg")}
                    />
                  </span>
                  <Media className="ml-2 d-none d-lg-block">
                    <span className="mb-0 text-sm font-weight-bold">
                      {firstName || "User"} {/* Display fetched first name or "User" if not available */}
                    </span>
                  </Media>
                </Media>
              </DropdownToggle>
              <DropdownMenu className="dropdown-menu-arrow" right>
                <DropdownItem className="noti-title" header tag="div">
                  <h6 className="text-overflow m-0">Welcome!</h6>
                </DropdownItem>
                <DropdownItem to="/admin/user-profile" tag={Link}>
                  <i className="ni ni-single-02" />
                  <span>My profile</span>
                </DropdownItem>
                <DropdownItem to="/admin/user-profile" tag={Link}>
                  <i className="ni ni-settings-gear-65" />
                  <span>Settings</span>
                </DropdownItem>
                <DropdownItem to="/admin/user-profile" tag={Link}>
                  <i className="ni ni-calendar-grid-58" />
                  <span>Activity</span>
                </DropdownItem>
                <DropdownItem to="/admin/user-profile" tag={Link}>
                  <i className="ni ni-support-16" />
                  <span>Support</span>
                </DropdownItem>
                <DropdownItem divider />
                {/* Modify the Logout dropdown item to handle Firebase logout */}
                <DropdownItem onClick={handleLogout}>
                  <i className="ni ni-user-run" />
                  <span>Logout</span>
                </DropdownItem>
              </DropdownMenu>
            </UncontrolledDropdown>
          </Nav>
        </Container>
      </Navbar>
    </>
  );
};

export default AdminNavbar;
